 height+=120;let body=lines(['YEASTVAR1011  /  '+c.text('atlas').toUpperCase()],pad,36,12,'#62758a',600)+lines(title,pad,titleY,30,'#1a344b',600,40)+lines([`${c.count('steps',plan.stages.length)}   ·   ${c.count('tools',plan.tools.length)}   ·   ${c.count('metrics',plan.metrics.length)}   ·   ${c.count('genes',plan.markers.length)}`],pad,rootBottom-20,16,'#617487');
